sections.code:
# This is your first BPL program!
# Lines starting with # are comments - they're ignored by the compiler

# We need printf to print text. 'extern' means it's defined elsewhere (C library)
extern printf(fmt: string, ...);

# Every BPL program starts with a 'main' frame (function)
# 'frame' = function, 'ret int' = returns an integer
frame main() ret int {
    # Print a message to the screen
    printf("Hello, BPL World!\n");

    # Return 0 means "success" (like in C)
    return 0;
}

